def stable_path_key(path: str | Path) -> str:
    normalized = Path(path).resolve().as_posix()
    repo = _repo_root().resolve().as_posix()
    if normalized.startswith(repo + "/"):
        relative = normalized[len(repo) + 1:]
    elif normalized == repo:
        relative = "."
    else:
        relative = normalized
    return "coord:" + hashlib.sha256(relative.encode("utf-8")).hexdigest()

@staticmethod
def _resolve_paths(paths, worktree_path, repo_root):
    if not paths: return paths
    if repo_root is None: return paths
    repo = Path(repo_root).resolve()
    worktree = Path(worktree_path).resolve() if worktree_path else None
    for raw in paths:
        resolved = Path(raw).resolve()
        resolved.relative_to(repo)  # raises ValueError if outside
        if worktree is not None:
            resolved.relative_to(worktree)
    return paths

